'use strict';
const KEY='islam-ajandasi-v1';
let state;try{state=JSON.parse(localStorage.getItem(KEY))||{}}catch{state={}};
state.checks ||= {};state.counts ||= {};state.goals ||= {};state.notes ||= {};state.custom ||= [];
const $=id=>document.getElementById(id), save=()=>localStorage.setItem(KEY,JSON.stringify(state));
const localDay=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const today=localDay();let selectedDay=today;
const safe=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const baseDhikrs=[['subhan','Sübhânallah',100],['elham','Elhamdülillah',100],['allahuekber','Allahu Ekber',100],['tevhid','Lâ ilâhe illallah',100],['istigfar','Estağfirullah',100],['tevbe','Estağfirullâhe ve etûbü ileyh',100],['bihamdihi','Sübhânallâhi ve bihamdihî',100],['azim','Sübhânallâhil azîm',100],['salavat','Salavat-ı Şerife',100],['lahavle','Lâ havle ve lâ kuvvete illâ billâh',100],['hasbiyallah','Hasbiyallâhu lâ ilâhe illâ Hû',100],['hayy','Yâ Hayyü Yâ Kayyûm',100],['fettah','Yâ Fettâh',489],['rezzak','Yâ Rezzâk',100],['safi','Yâ Şâfî',100],['vedud','Yâ Vedûd',400]];
const plans=[
['hatim','Kur’an-ı Kerim Hatmi',30,'cüz','Program 8'],['tevhid70','Kelime-i Tevhid',70,'1.000’lik bölüm','Program 9'],['istigfar70','İstiğfar',70,'1.000’lik bölüm','Program 10'],['salavat70','Salavat',70,'1.000’lik bölüm','Program 11'],['mulk','Mülk Suresi',100,'okuma','Program 13'],['vakia','Vakıa Suresi',100,'okuma','Program 14'],['amme','Amme Suresi',100,'okuma','Program 15'],['yasin100','Yasin Suresi',100,'okuma','Program 16'],['fetih','Fetih Suresi',100,'okuma','Program 17'],['fatiha313','Fâtiha Suresi',313,'okuma','Program 18'],['ayet313','Âyetel Kürsî',313,'okuma','Program 19'],['kevser21','21 Gün · 100 Kevser Suresi',21,'gün','Program 20'],['ihlas40','İhlâs-ı Şerif Hatmi',40,'1.000’lik bölüm','Program 21'],['insirah40','İnşirah Suresi',40,'1.000’lik bölüm','Program 23'],['yasin41','Yasin-i Şerif Hatmi',41,'okuma','Program 24'],['kamp41','41 Günlük Manevi Kamp',41,'gün','Program 6'],['teheccud30','30 Günlük Teheccüd',30,'gün','Program 25'],['yunus12','Yunus Aleyhisselam Duası',12,'1.000’lik bölüm','Program 4']];
function check(id){return !!state.checks[id]}function setCheck(id,v){state.checks[id]=v;save()}
function show(screen){document.querySelectorAll('.screen').forEach(e=>e.classList.toggle('hidden',e.id!==screen));document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.screen===screen));if(screen==='home')renderHome();if(screen==='dhikr'){renderDhikr();renderDhikrEsma();}if(screen==='plans')renderPlans();if(screen==='worship')renderWorship();if(screen==='more'){renderMore();$('export')?.closest('.panel')?.setAttribute('id','dataBackupPanel');}if(screen==='prophets')renderProphets();window.scrollTo(0,0)}
document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>show(b.dataset.screen)));
function progress(id,n){let c=0;for(let i=1;i<=n;i++)if(check(`plan:${id}:${i}`))c++;return c}
function renderHome(){const date=new Date(today+'T12:00:00');$('today').textContent=date.toLocaleDateString('tr-TR',{weekday:'long',day:'numeric',month:'long',year:'numeric'});renderHomeIndex()}


$('dhikrDate').value=today;$('dhikrDate').onchange=e=>{selectedDay=e.target.value||today;renderDhikr()};
let editing=null;function allDhikrs(){return [...baseDhikrs,...state.custom].filter(x=>!state.checks[`hidden:${x[0]}`])}
function renderDhikr(){let list=$('dhikrList');list.replaceChildren();for(const [id,baseName,baseGoal] of allDhikrs()){let name=state.goals[`name:${id}`]||baseName,goal=Number(state.goals[id]||baseGoal),k=`${selectedDay}:${id}`,n=Number(state.counts[k]||0);let row=document.createElement('div');row.className='tracker';let info=document.createElement('div');info.className='info';let strong=document.createElement('strong');strong.textContent=name;let small=document.createElement('small');small.textContent=n>=goal?'Elhamdülillah, zikir tamamlandı.':'Hedefe '+(goal-n)+' kaldı';info.append(strong,small);let count=document.createElement('span');count.className='count';count.textContent=n+' / '+goal;let minus=document.createElement('button');minus.textContent='−';minus.setAttribute('aria-label',name+' azalt');minus.onclick=()=>{state.counts[k]=Math.max(0,n-1);save();renderDhikr()};let plus=document.createElement('button');plus.className='plus';plus.textContent='+1';plus.disabled=n>=goal;plus.onclick=()=>{state.counts[k]=Math.min(goal,n+1);save();let left=goal-state.counts[k];if(navigator.vibrate){try{navigator.vibrate(left===0?[300,100,350]:left===1?180:left===2?100:left===3?60:12)}catch{}}renderDhikr()};let edit=document.createElement('button');edit.className='edit';edit.textContent='Düzenle';edit.onclick=()=>openEdit(id,name,goal);row.append(info,count,minus,plus,edit);list.append(row)}}
function openEdit(id,name,goal){editing=id;$('editName').value=name;$('editGoal').value=goal;$('editDialog').showModal()}
$('addDhikr').onclick=()=>openEdit(null,'',100);
$('editForm').addEventListener('submit',e=>{if(e.submitter?.value!=='save')return;let name=$('editName').value.trim(),goal=Number($('editGoal').value);if(!name||!Number.isInteger(goal)||goal<1||goal>100000){e.preventDefault();alert('Geçerli ad ve hedef gir.');return}let id=editing;if(!id){id='ozel-'+Date.now();state.custom.push([id,name,goal])}state.goals[`name:${id}`]=name;state.goals[id]=goal;save();renderDhikr()});
function renderPlanInto(container,filter){container.replaceChildren();for(const [id,title,n,unit,source] of plans.filter(filter)){const c=progress(id,n),panel=document.createElement('div');panel.className='panel';panel.id='plan-'+id;panel.innerHTML=`<div class="row"><h3>${safe(title)}</h3><span class="pill">${c}/${n}</span></div><small class="hint">${safe(source)} · Her kutu 1 ${safe(unit)} temsil eder</small><div class="progress"><div style="width:${c/n*100}%"></div></div><div class="gridcells"></div>`;const grid=panel.querySelector('.gridcells');for(let i=1;i<=n;i++){let btn=document.createElement('button');btn.className='cell'+(check(`plan:${id}:${i}`)?' checked':'');btn.textContent=i;btn.setAttribute('aria-label',title+' '+i+' '+unit);btn.setAttribute('aria-pressed',check(`plan:${id}:${i}`));btn.onclick=()=>{setCheck(`plan:${id}:${i}`,!check(`plan:${id}:${i}`));renderPlanInto(container,filter)};grid.append(btn)}container.append(panel)}}
function renderPlans(){renderPlanInto($('planList'),x=>!['teheccud30','kamp41'].includes(x[0]));renderPrayerProgram()}
const prayers=['Sabah','Öğle','İkindi','Akşam','Yatsı','Vitir'];
function renderWorship(){let root=$('worshipContent');root.innerHTML='<div class="panel" id="dailyPrayerPanel"><h3>Günlük namaz takibi</h3><label>Tarih<input type="date" id="prayerDate"></label><div id="prayerChecks"></div></div><div class="panel" id="kazaPrayerPanel"><h3>Kaza namazları</h3><p class="hint">Her işaret bir kaza namazı kaydıdır.</p><div id="kaza"></div></div><div class="panel" id="kazaFastPanel"><h3>Kaza oruçları</h3><p class="hint">Tamamlanan günleri işaretle.</p><label>Toplam hedef (gün)<input id="fastGoal" type="number" min="1" max="3650"></label><div id="fastGrid" class="gridcells"></div></div>';let date=$('prayerDate');date.value=today;function drawPrayers(){let box=$('prayerChecks');box.replaceChildren();prayers.forEach(p=>{let row=document.createElement('div');row.className='checkrow';let cb=document.createElement('input');cb.type='checkbox';let k=`prayer:${date.value}:${p}`;cb.checked=check(k);cb.onchange=()=>setCheck(k,cb.checked);let label=document.createElement('label');label.textContent=p+' namazı';row.append(cb,label);box.append(row)})}date.onchange=drawPrayers;drawPrayers();let kaza=$('kaza');prayers.forEach(p=>{let k=`kaza:${p}`,n=Number(state.counts[k]||0),row=document.createElement('div');row.className='tracker';row.innerHTML=`<div class="info"><strong>${p}</strong><small>Tamamlanan toplam</small></div><span class="count">${n}</span>`;let minus=document.createElement('button');minus.textContent='−';minus.onclick=()=>{state.counts[k]=Math.max(0,n-1);save();renderWorship()};let plus=document.createElement('button');plus.textContent='+1';plus.onclick=()=>{state.counts[k]=n+1;save();renderWorship()};row.append(minus,plus);kaza.append(row)});let fg=$('fastGoal');fg.value=state.goals.fast||30;fg.onchange=()=>{state.goals.fast=Math.max(1,Math.min(3650,Number(fg.value)||30));save();renderWorship()};let grid=$('fastGrid');for(let i=1;i<=Number(fg.value);i++){let b=document.createElement('button');b.className='cell'+(check('fast:'+i)?' checked':'');b.textContent=i;b.onclick=()=>{setCheck('fast:'+i,!check('fast:'+i));b.classList.toggle('checked',check('fast:'+i))};grid.append(b)}}
