function navigateTo(screen,target){
 show(screen);
 if(target)requestAnimationFrame(()=>requestAnimationFrame(()=>{
  const el=document.getElementById(target);
  if(el){el.scrollIntoView({behavior:'smooth',block:'start'});el.classList.add('target-flash');setTimeout(()=>el.classList.remove('target-flash'),1500)}
 }));
}

